/* Técnica clásica de centrado con translate */
.modal {
  position: fixed;
  top: 50%;
  left: 50%;
  /* El 50% es relativo al propio elemento */
  transform: translate(-50%, -50%);
  /* Resultado: perfectamente centrado en pantalla */
}

/* Hover con múltiples transforms */
.tarjeta {
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}

.tarjeta:hover {
  /* Sube 8px, gira ligeramente y crece un poco */
  transform: translateY(-8px) rotate(2deg) scale(1.02);
  box-shadow: 0 12px 24px rgba(0,0,0,0.15);
}

/* Demostrando que el ORDEN importa en transforms */

/* Caso 1: primero rotar, luego trasladar */
/* La traslación ocurre en el sistema de coordenadas rotado */
.caja-a:hover {
  transform: rotate(45deg) translateX(100px);
  /* Se mueve 100px en dirección diagonal (el eje X fue rotado) */
}

/* Caso 2: primero trasladar, luego rotar */
/* El elemento se mueve 100px a la derecha y LUEGO rota en su lugar */
.caja-b:hover {
  transform: translateX(100px) rotate(45deg);
}

/* transform-origin: la puerta que se abre */
.puerta {
  transform-origin: left center; /* pivote en el borde izquierdo */
}

.puerta:hover {
  transform: rotateY(70deg); /* se abre hacia la derecha */
}

/* Icono que gira al hacer hover en el padre */
.boton:hover .icono {
  transform: rotate(180deg);
}
